import {useEffect,useState} from 'react';
import {defineLocalTool,type LocalToolProps,type LocalToolJson} from '@/engines/local/sdk';
export type AuthorState={version:1;notes:string};
function View({client}:LocalToolProps<AuthorState>){const [notes,setNotes]=useState(''),[status,setStatus]=useState('Opening');useEffect(()=>{let live=true;void client.read().then(row=>{if(live){setNotes(row.data.notes);setStatus('Ready');}});return()=>{live=false;};},[client]);return <section className="mx-auto max-w-3xl space-y-4 p-5 text-text-primary"><h2 className="font-display text-2xl">Author host notebook</h2><textarea rows={6} className="block w-full rounded-lg border border-border bg-elevated p-3 outline-none focus:border-accent-gold" aria-label="Author notes" value={notes} onChange={event=>setNotes(event.target.value)}/><button className="mr-3 min-h-9 rounded-lg border border-border px-3 py-2 text-sm focus-visible:outline-2 focus-visible:outline-accent-gold" onClick={()=>void client.read().then(row=>client.save({version:1,notes},row.revision)).then(()=>setStatus('Saved'))}>Save author notes</button><button className="mr-3 min-h-9 rounded-lg border border-border px-3 py-2 text-sm focus-visible:outline-2 focus-visible:outline-accent-gold" onClick={()=>void client.openDocument('codex','author-card')}>Open linked card</button><p role="status">{status}</p></section>;}
const empty={type:'object' as const,properties:{},additionalProperties:false};
export default defineLocalTool<AuthorState>({namespace:'tests.author-kit',name:{en:'Author kit notebook',es:'Cuaderno del kit de autor'},description:{en:'Synthetic host contract fixture.',es:'Fixture sintética de contrato.'},initialState:{version:1,notes:''},validateState:(value:LocalToolJson):value is AuthorState=>!!value&&typeof value==='object'&&!Array.isArray(value)&&value.version===1&&typeof value.notes==='string',component:View,operations:[
{id:'append',writes:true,description:{en:'Append a note.',es:'Añadir nota.'},inputSchema:{type:'object',properties:{text:{type:'string',minLength:1},revision:{type:['integer','null'],minimum:0}},required:['text','revision'],additionalProperties:false},run:async(input,client)=>{const before=await client.read();const next=await client.save({version:1,notes:before.data.notes+String(input.text)},input.revision as number|null);return{revision:next.revision,data:next.data,provenance:next.provenance??'base'};}},
{id:'inspect',writes:false,description:{en:'Inspect effective fixtures.',es:'Leer fixtures efectivas.'},inputSchema:empty,run:async(_input,client)=>{const read=(await client.world.read('codex','author-card'))!,state=await client.read();return{notes:state.data.notes,revision:state.revision,provenance:state.provenance??'base',title:read.document.root.title as string,total:read.projection!.fields.total,cards:(await client.queryCodex()).map(card=>({title:card.title,total:card.fields.total})),variants:!!client.world.variants,search:(await client.search('guide')).map(row=>row.title)};}},
{id:'fail',writes:true,description:{en:'Reject after a save.',es:'Rechazar tras guardar.'},inputSchema:empty,run:async(_input,client)=>{const row=await client.read();await client.save({version:1,notes:'REJECTED'},row.revision);throw Error('author_failure');}},
{id:'invalid_result',writes:true,description:{en:'Reject an invalid result.',es:'Rechazar resultado inválido.'},inputSchema:empty,run:async(_input,client)=>{const row=await client.read();await client.save({version:1,notes:'REJECTED RESULT'},row.revision);return undefined as unknown as LocalToolJson;}},
{id:'lying_query',writes:false,description:{en:'Try to save from a query.',es:'Intentar guardar en consulta.'},inputSchema:empty,run:async(_input,client)=>{const row=await client.read();await client.save({version:1,notes:'READONLY FAILURE'},row.revision);return null;}},
{id:'fail_variant',writes:true,description:{en:'Reject after variant write.',es:'Rechazar tras escribir variante.'},inputSchema:empty,run:async(_input,client)=>{const row=(await client.world.read('codex','author-card'))!;await client.world.variants!.save('codex',{...row.document,root:{...row.document.root,title:'REJECTED VARIANT'}},row.version);throw Error('author_variant_failure');}},
]});
